arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_e423474f6a4f47de869818cd82f1d923.Models
@using sv_e423474f6a4f47de869818cd82f1d923.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1 class="mb-4">Job Application</h1>

<StepIndicator CurrentStep="currentStep"
               CompletedSteps="completedSteps"
               OnStepClicked="GoToStep" />

<div class="mt-4">
    @if (currentStep == 1)
    {
        <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                          FullNameChanged="v => fullName = v" EmailChanged="v => email = v"
                          PhoneChanged="v => phone = v" AddressChanged="v => address = v"
                          OnNext="HandlePersonalInfoNext"
                          ValidationError="@personalInfoError" IsValidating="@isValidatingEmail" />
    }
    else if (currentStep == 2)
    {
        <WorkHistoryStep Entries="workEntries" OnBack="GoBack" OnNext="HandleWorkHistoryNext"
                         ValidationError="@workHistoryError" />
    }
    else if (currentStep == 3)
    {
        <ReferencesStep References="references" OnBack="GoBack" OnNext="HandleReferencesNext"
                        ValidationError="@referencesError" />
    }
    else if (currentStep == 4)
    {
        <CoverLetterStep CoverLetter="@coverLetter" CoverLetterChanged="v => coverLetter = v"
                         OnBack="GoBack" OnNext="HandleCoverLetterNext"
                         ValidationError="@coverLetterError" />
    }
    else if (currentStep == 5)
    {
        <ReviewStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                    WorkEntries="workEntries" References="references" CoverLetter="@coverLetter"
                    OnEditSection="GoToStep" OnSubmit="HandleSubmit"
                    OnBack="GoBack" IsSubmitting="@isSubmitting"
                    IsSubmitted="@isSubmitted" ApplicationId="@applicationId" />
    }
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();

    // Step 1 — Personal Info
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";
    private string? personalInfoError;
    private bool isValidatingEmail;

    // Step 2 — Work History
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private string? workHistoryError;

    // Step 3 — References
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string? referencesError;

    // Step 4 — Cover Letter
    private string coverLetter = "";
    private string? coverLetterError;

    // Step 5 — Submission
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;

    private void GoToStep(int step)
    {
        if (step < currentStep || completedSteps.Contains(step) || step == currentStep)
        {
            currentStep = step;
            ClearErrors();
        }
    }

    private void GoBack()
    {
        if (currentStep > 1)
        {
            currentStep--;
            ClearErrors();
        }
    }

    private void ClearErrors()
    {
        personalInfoError = null;
        workHistoryError = null;
        referencesError = null;
        coverLetterError = null;
    }

    private async Task HandlePersonalInfoNext()
    {
        if (string.IsNullOrWhiteSpace(fullName))
        {
            personalInfoError = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(email))
        {
            personalInfoError = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(phone))
        {
            personalInfoError = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(address))
        {
            personalInfoError = "Address is required.";
            return;
        }

        isValidatingEmail = true;
        personalInfoError = null;
        StateHasChanged();

        var isEmailValid = await ApplicationService.ValidateEmailAsync(email);
        isValidatingEmail = false;

        if (!isEmailValid)
        {
            personalInfoError = "Please enter a valid email address.";
            return;
        }

        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleWorkHistoryNext()
    {
        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                workHistoryError = "Company name and job title are required for all entries.";
                return;
            }
            if (entry.StartDate == default)
            {
                workHistoryError = "Start date is required for all entries.";
                return;
            }
        }

        workHistoryError = null;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleReferencesNext()
    {
        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            {
                referencesError = "Name and email are required for all references.";
