{"file_text": "<div class="d-flex align-items-center justify-content-between mb-3 step-indicator">
    @for (int i = 1; i <= stepNames.Length; i++)
    {
        var step = i;
        var isCurrent = step == CurrentStep;
        var isCompleted = CompletedSteps.Contains(step);
        var isFuture = step > CurrentStep && !isCompleted;
        var cssClass = isCurrent ? "step current" : isCompleted ? "step completed" : "step future";
        var isClickable = isCompleted;

        <div class="@cssClass text-center flex-fill"
             style="cursor: @(isClickable ? "pointer" : "default")"
             @onclick="() => { if (isClickable) OnStepClicked.InvokeAsync(step); }">
            <div class="step-circle mx-auto mb-1 @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-secondary text-white")"
                 style="width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:0.85rem;">
                @if (isCompleted)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@step</span>
                }
            </div>
            <small class="@(isFuture ? "text-muted" : "")">@stepNames[step - 1]</small>
        </div>

        @if (step < stepNames.Length)
        {
            <div class="flex-fill d-flex align-items-center" style="max-width:60px;">
                <hr class="w-100 @(CompletedSteps.Contains(step) ? "border-success" : "border-secondary")" />
            </div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] stepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };
}
